function loadFavorites(){try{favorites=JSON.parse(localStorage.getItem('spotify_pins_'+favoriteUser)||'{}');if(!favorites||Array.isArray(favorites)||typeof favorites!=='object')favorites={}}catch(e){favorites={}}}
